    'concept_natural_beauty_desc' => 'ਤੁਹਾਡੀ ਅਤੇ ਧਰਤੀ ਦੀ ਪਰਵਾਹ ਕਰਨ ਵਾਲੇ ਵਾਤਾਵਰਣ-ਸਚੇਤ ਸੈਲੂਨਾਂ ਨਾਲ ਜੁੜੋ। ਟਿਕਾਊ ਸੁੰਦਰਤਾ ਇੱਥੇ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ।',
    'concept_art_of_beauty' => 'ਸੁੰਦਰਤਾ<br>ਦੀ ਕਲਾ',
    'concept_art_of_beauty_desc' => 'ਸਭ ਤੋਂ ਵਧੀਆ ਸੰਸਥਾਵਾਂ ਵਿੱਚ ਵਿਸ਼ੇਸ਼ ਸੁੰਦਰਤਾ ਸੇਵਾਵਾਂ ਦਾ ਅਨੁਭਵ ਕਰੋ। ਜਿੱਥੇ ਲਗਜ਼ਰੀ ਸੰਪੂਰਨਤਾ ਨੂੰ ਮਿਲਦੀ ਹੈ।',
    'concept_discover_glow' => 'ਆਪਣੀ ਸੰਪੂਰਨ<br>ਚਮਕ ਖੋਜੋ',
    'concept_discover_glow_desc' => 'ਆਧੁਨਿਕ ਵਿਅਕਤੀ ਲਈ ਤਿਆਰ ਕੀਤੇ ਪ੍ਰੀਮੀਅਮ ਸੁੰਦਰਤਾ ਅਨੁਭਵ। ਸਿਖਰਲੇ ਦਰਜੇ ਵਾਲੇ ਸੈਲੂਨਾਂ ਵਿੱਚ ਵਿਸ਼ੇਸ਼ ਇਲਾਜ ਬੁੱਕ ਕਰੋ।',
